/* @lc app=leetcode id=3480 lang=kotlin */ class Solution { fun upd(st: IntArray, lo: Int, id: Int) = if (lo > st[0]) st.set(2, st[0]).also { st[0] = lo }.also { st[1] = id } else if (lo > st[2]) st.set(2, lo) else Unit fun maxSubarrays(n: Int, conflictingPairs: Array<IntArray>): Long = conflictingPairs.indices.groupBy { maxOf(conflictingPairs[it][0], conflictingPairs[it][1]) }.let { gr -> IntArray(3).also { it[1] = -1 }.let { st -> LongArray(conflictingPairs.size).let { gain -> (1..n).fold(0L) { base, r -> gr[r].orEmpty().forEach { id -> upd(st, minOf(conflictingPairs[id][0], conflictingPairs[id][1]), id) }.let { if (st[1] >= 0) gain[st[1]] += (st[0] - st[2]).toLong() }.let { base + (r - st[0]) } } + (gain.maxOrNull() ?: 0L) } } } }